// /employees/123: a DYNAMIC route. The folder name [id] becomes params.id
// (like {id} in [HttpGet("{id}")] or a route template in MVC).
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { EmployeeDetails } from "@/components/employees/EmployeeDetails";

export const metadata: Metadata = { title: "Employee details" };

// PageProps<"/employees/[id]"> is generated by Next.js → `params` is typed as Promise<{ id: string }>.
// Reading params is request-time work; the sibling loading.tsx provides the Suspense fallback.
export default async function EmployeeDetailsPage({ params }: PageProps<"/employees/[id]">) {
  const { id } = await params;
  const employeeId = Number(id);
  if (!Number.isInteger(employeeId) || employeeId <= 0) notFound(); // /employees/abc → 404 page

  return <EmployeeDetails id={employeeId} />;
}
